/// Pluggable Assist Services: 6-Tier Hints, Proximity Radar, Stall Detector, and Time Bonuses.
/// Pure Dart domain/application service — zero UI coupling.
/// Ported from Python assists/ directory.
library;

import 'package:equatable/equatable.dart';

import '../../../../core/models/models.dart';
import '../domain/game_state.dart';

// ─────────────────────────────────────────────────────────
// Progressive Hint Result & Provider
// ─────────────────────────────────────────────────────────

/// Result payload generated by the 6-tier progressive hint system.
class ProgressiveHintResult extends Equatable {
  const ProgressiveHintResult({
    required this.wordEntry,
    required this.tier,
    required this.message,
    required this.highlightCoords,
  });

  final WordEntry wordEntry;
  final HintTier tier;
  final String message;
  final List<(int, int)> highlightCoords;

  @override
  List<Object?> get props => [wordEntry, tier, message, highlightCoords];
}

/// Provides granular, step-by-step progressive hints (Tiers 1–6).
class ProgressiveHintProvider {
  const ProgressiveHintProvider();

  /// Escalates or provides the next allowed hint tier for [targetWordStr] (or first unfound word).
  ProgressiveHintResult? requestHint(
    GameState gameState, {
    String? targetWordStr,
  }) {
    final unfoundWords =
        gameState.puzzle.words.where((w) => !w.found).toList();
    if (unfoundWords.isEmpty) return null;

    // Pick target word
    WordEntry? target;
    if (targetWordStr != null) {
      for (final w in unfoundWords) {
        if (w.word == targetWordStr) {
          target = w;
          break;
        }
      }
    }
    target ??= unfoundWords.first;

    final allowedTiers = [...gameState.puzzle.assistConfig.allowedHintTiers]
      ..sort();
    if (allowedTiers.isEmpty) return null;

    final currentLevel = target.hintTierUsed.level;
    final higherTiers = allowedTiers.where((t) => t > currentLevel).toList();

    final nextTier = higherTiers.isNotEmpty
        ? HintTier.fromLevel(higherTiers.first)
        : (target.hintTierUsed != HintTier.none
            ? target.hintTierUsed
            : HintTier.fromLevel(allowedTiers.last));

    final updatedTarget = target.copyWith(hintTierUsed: nextTier);

    String msg = '';
    List<(int, int)> highlightCoords = const [];

    switch (nextTier) {
      case HintTier.none:
        msg = 'No hint available.';
      case HintTier.tier1Clue:
        msg = 'Clue: ${target.clue ?? 'No clue available for this word.'}';
      case HintTier.tier2WordName:
        msg = "Word: '${target.word}' (${target.length} letters)";
        if (target.reading != null && target.reading!.isNotEmpty) {
          msg += ' [Reading: ${target.reading}]';
        }
      case HintTier.tier3FirstLetter:
        final firstChar = target.word.isNotEmpty ? target.word[0] : '?';
        msg = "Starts with '$firstChar' (${target.length} letters)";
      case HintTier.tier4Orientation:
        final dirName = target.direction?.humanReadable ?? 'Unknown direction';
        msg = "Word '${target.word}' is placed $dirName";
      case HintTier.tier5StartCoordinate:
        if (target.startCoord != null) {
          final (r, c) = target.startCoord!;
          highlightCoords = [(r, c)];
          msg = "'${target.word}' starts at Row ${r + 1}, Col ${c + 1}";
        }
      case HintTier.tier6FullGlow:
        highlightCoords = List.from(target.coords);
        msg = "Revealing full path for '${target.word}'";
    }

    return ProgressiveHintResult(
      wordEntry: updatedTarget,
      tier: nextTier,
      message: msg,
      highlightCoords: highlightCoords,
    );
  }
}

// ─────────────────────────────────────────────────────────
// Proximity Radar Feedback & Provider
// ─────────────────────────────────────────────────────────

/// Hot/Cold temperature radar feedback for cell exploration.
class ProximityFeedback extends Equatable {
  const ProximityFeedback({
    required this.status,
    required this.distance,
    required this.message,
    required this.colorValue,
    required this.coord,
  });

  final String status;
  final double distance;
  final String message;
  final int colorValue;
  final (int, int) coord;

  @override
  List<Object?> get props => [status, distance, message, colorValue, coord];
}

/// Provides real-time Hot & Cold proximity radar feedback when tapping or inspecting cells.
class ProximityAssistProvider {
  ProximityAssistProvider({this.throttleIntervalSeconds = 0.10});

  final double throttleIntervalSeconds;
  double _lastCalcTimestamp = 0.0;
  (int, int)? _cachedCoord;
  ProximityFeedback? _cachedResult;

  /// Calculates proximity with caching for identical coordinates.
  ProximityFeedback? calculateProximity(
    GameState gameState,
    (int, int) coord, {
    double? currentTimestamp,
  }) {
    if (!gameState.puzzle.assistConfig.proximityEnabled) {
      return null;
    }

    final now = currentTimestamp ??
        (DateTime.now().millisecondsSinceEpoch / 1000.0);

    if (_cachedCoord == coord &&
        (now - _lastCalcTimestamp) < throttleIntervalSeconds) {
      return _cachedResult;
    }

    _lastCalcTimestamp = now;
    _cachedCoord = coord;

    final dist = gameState.getNearestUnfoundWordDistance(coord);
    if (dist == null) {
      _cachedResult = null;
      return null;
    }

    final String status;
    final String message;
    final int colorValue;

    if (dist <= 1.0) {
      status = 'BURNING';
      message = '🔥 Burning Hot! A word starts right here!';
      colorValue = 0xFFFF3C3C;
    } else if (dist <= 2.0) {
      status = 'HOT';
      message = '⚡ Hot! Very close to a word start.';
      colorValue = 0xFFFF8C00;
    } else if (dist <= 3.5) {
      status = 'WARM';
      message = '✨ Warm... in the right neighborhood.';
      colorValue = 0xFFFFD700;
    } else if (dist <= 5.0) {
      status = 'COOL';
      message = '❄️ Cool. Still a bit far.';
      colorValue = 0xFF64B4FF;
    } else {
      status = 'COLD';
      message = '🧊 Cold.';
      colorValue = 0xFF9696B4;
    }

    final result = ProximityFeedback(
      status: status,
      distance: (dist * 100).roundToDouble() / 100.0,
      message: message,
      colorValue: colorValue,
      coord: coord,
    );

    _cachedResult = result;
    return result;
  }
}

// ─────────────────────────────────────────────────────────
// Auto Stall Detector
// ─────────────────────────────────────────────────────────

/// Detects player stall or struggle and triggers assistance reminders.
class AutoStallDetector {
  AutoStallDetector({this.stallThresholdSeconds = 45.0});

  final double stallThresholdSeconds;
  double secondsSinceLastFind = 0.0;
  bool stallTriggered = false;

  /// Ticks inactivity clock; returns reminder message if threshold exceeded.
  String? onTick(GameState gameState, double deltaSeconds) {
    if (gameState.status != GameStatus.playing || gameState.isComplete) {
      return null;
    }

    secondsSinceLastFind += deltaSeconds;
    if (secondsSinceLastFind >= stallThresholdSeconds && !stallTriggered) {
      stallTriggered = true;
      return 'Need a hint? Tap the Clue button or a word in the word bank!';
    }
    return null;
  }

  /// Resets inactivity clock when a word is solved.
  void onWordFound() {
    secondsSinceLastFind = 0.0;
    stallTriggered = false;
  }

  void reset() {
    secondsSinceLastFind = 0.0;
    stallTriggered = false;
  }
}

// ─────────────────────────────────────────────────────────
// Time Bonus Assist Provider
// ─────────────────────────────────────────────────────────

/// Manages word solve bonuses and emergency overtime recovery.
class TimeBonusAssistProvider {
  const TimeBonusAssistProvider();

  /// Adds emergency time in Timed Attack mode.
  double applyEmergencyTimeBoost(GameState gameState, {double boostSeconds = 30.0}) {
    if (gameState.mode != GameMode.timedAttack) return gameState.timeRemaining;
    return gameState.timeRemaining + boostSeconds;
  }
}

// ─────────────────────────────────────────────────────────
// Central Assists Service Facade
// ─────────────────────────────────────────────────────────

/// Unified facade coordinating hints, proximity, stall detection, and time boosts.
class AssistsService {
  AssistsService({
    ProgressiveHintProvider? hintProvider,
    ProximityAssistProvider? proximityProvider,
    AutoStallDetector? stallDetector,
    TimeBonusAssistProvider? timeBonusProvider,
  })  : hints = hintProvider ?? const ProgressiveHintProvider(),
        proximity = proximityProvider ?? ProximityAssistProvider(),
        stallDetector = stallDetector ?? AutoStallDetector(),
        timeBonus = timeBonusProvider ?? const TimeBonusAssistProvider();

  final ProgressiveHintProvider hints;
  final ProximityAssistProvider proximity;
  final AutoStallDetector stallDetector;
  final TimeBonusAssistProvider timeBonus;

  /// Requests the next progressive hint for a word.
  ProgressiveHintResult? requestHint(GameState state, {String? targetWord}) =>
      hints.requestHint(state, targetWordStr: targetWord);

  /// Inspects proximity of [coord] relative to word starts.
  ProximityFeedback? checkProximity(GameState state, (int, int) coord) =>
      proximity.calculateProximity(state, coord);

  /// Ticks stall detector; returns notification message if stalled.
  String? checkStall(GameState state, double deltaSeconds) =>
      stallDetector.onTick(state, deltaSeconds);

  /// Resets stall clock on discovery.
  void notifyWordFound() => stallDetector.onWordFound();

  /// Applies emergency overtime recovery.
  double emergencyTimeBoost(GameState state, {double boostSeconds = 30.0}) =>
      timeBonus.applyEmergencyTimeBoost(state, boostSeconds: boostSeconds);
}

